private void handleAction(Player player, CityMenuGui gui, CityMenuGui.CityAction action) {
  if (action == CityMenuGui.CityAction.DEPOSIT) {
    openAmountInput(player, CityAmountGui.Operation.DEPOSIT);
    return;

  ItemStack previousHand = player.getInventory().getItemInMainHand().clone();
  pendingAmounts.put(
      player.getUniqueId(), new PendingAmount(operation, city.get().id(), previousHand));
  player.closeInventory();
  ItemStack book = new ItemStack(org.bukkit.Material.WRITABLE_BOOK);
  BookMeta meta = (BookMeta) book.getItemMeta();
  meta.setTitle("City amount");
  meta.setAuthor("StarCore");
  meta.addPage("");
  book.setItemMeta(meta);
  player.getInventory().setItemInMainHand(book);
  player.sendActionBar(Component.text("右键打开输入书本，填写金额后签名确认。", NamedTextColor.YELLOW));
}

